def _join_compat(
    self, other, on=None, how="left", lsuffix="", rsuffix="", sort=False
):
    from pandas.core.reshape.merge import merge
    from pandas.core.reshape.concat import concat

    # Ensure the 'other' parameter is a DataFrame or Series
    if isinstance(other, Series):
        if other.name is None:
            raise ValueError("Other Series must have a name")
        other = DataFrame({other.name: other})

    if isinstance(other, DataFrame):
        return merge(
            self,
            other,
            left_on=on,
            how=how,
            left_index=on is None,
            right_index=True,
            suffixes=(lsuffix, rsuffix),
            sort=sort,
        )
    else:
        if on is not None:
            raise ValueError(
                "Joining multiple DataFrames only supported for joining on index"
            )

        frames = [self] + list(other)

        # Check if concatenation is possible with unique indices
        can_concat = all(df.index.is_unique for df in frames)

        # Join indexes only using concat if possible
        if can_concat:
            if how == "left":
                # Use concat for joining when indices are unique
                res = concat(frames, axis=1, join="outer", verify_integrity=False)
                return res.reindex(self.index, copy=False)
            else:
                # You might use different join types, hence consider 'how'
                return concat(frames, axis=1, join=how, verify_integrity=False)

        # If concatenation is not possible, perform merging iteratively
        joined = frames[0]

        for frame in frames[1:]:
            joined = merge(
                joined, frame, how=how, left_index=True, right_index=True
            )

        return joined
